        for (j = 0; j < ny; j++) {
#pragma HLS PIPELINE II=1
            hz_buf[i][j] = hz[i][j];
        }

    // ---- Compute phase: operate entirely on local buffers ----
compute_time:
    for (t = 0; t < tmax; t++)
